import{_ as t,o as i,c as p,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Patrick McGarry @ Ceph Day Paris","description":"","frontmatter":{"title":"Patrick McGarry @ Ceph Day Paris","date":"2014-11-10T00:00:00.000Z","updated":"2014-11-10T00:00:00.000Z","tags":["Ceph社区","分布式存储","红帽","开发进展","用户体验"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/Patrick_McGarry_@_Ceph_Day_Paris.md","filePath":"posts/2014/Patrick_McGarry_@_Ceph_Day_Paris.md","lastUpdated":1780459816000}'),r={name:"posts/2014/Patrick_McGarry_@_Ceph_Day_Paris.md"};function s(a,e,o,n,C,_){return i(),p("div",null,[...e[0]||(e[0]=[l("<p>会议纪要</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>会议主题</strong>： Ceph 社区更新、开发里程碑、未来方向</p><p><strong>参会人员</strong>： Ceph 社区成员、开发者、红帽员工</p><p><strong>会议内容</strong>：</p><p><strong>一、社区现状</strong></p><ul><li>红帽收购 Ceph 后，积极支持社区发展，并逐渐将 Ceph 社区融入红帽生态系统。</li><li>Ceph 社区将继续支持 Ubuntu 和 SUSE，并专注于红帽发行版，特别是 CentOS 和 Fedora。</li><li>红帽将同时支持 Ceph 和 Gluster，确保两个社区都不会被边缘化。</li></ul><p><strong>二、社区活动</strong></p><ul><li>Ceph Days 将更加注重开发者活动，并鼓励社区成员参与。</li><li>社区将扩展 metrics.ceph.com 网站，收集和分析社区指标，并与社区分享。</li><li>用户委员会将负责 Ceph 社区的治理，包括 Ceph.com、博客等。</li><li>Ceph 社区将继续参与 Google Summer of Code，为学生提供项目机会。</li><li>Ceph 社区将与 CentOS 合作，推动 Ceph 在 CentOS 上的应用。</li></ul><p><strong>三、开发进展</strong></p><ul><li>Giant 版已进入功能冻结阶段，即将发布 0.85 版本，其中包括 RDMA 支持、SSD 改进、CivetWeb 前端等。</li><li>RBD 将默认开启客户端缓存，并支持与 Eucalyptus 集成。</li><li>RGW 将改进 CivetWeb 前端，并处理桶限制问题。</li><li>CFS 将获得更多资源支持，并逐渐进入生产环境。</li><li>Ceph 支持 Chef、Puppet、Ansible等多种编排和部署工具。</li></ul><p><strong>四、行动计划</strong></p><ul><li>继续支持 Ubuntu 和 SUSE 发行版。</li><li>加强与 CentOS 合作。</li><li>持续改进 Ceph 功能和性能。</li><li>扩大 Ceph 社区规模。</li><li>加强 Ceph 社区的治理。</li></ul><p><strong>五、后续行动</strong></p><ul><li>Ceph 社区成员积极参与 Ceph Days、用户委员会等活动。</li><li>关注 Ceph 开发者 summit 和 blueprint 调查。</li><li>提供反馈和建议，帮助改进 Ceph。</li></ul><p><strong>关键词</strong>： Ceph, 红帽, Giant, Ceph Days, 用户委员会, Google Summer of Code, CentOS, CFS, 部署,编排</p>",16)])])}const u=t(r,[["render",s]]);export{c as __pageData,u as default};
